CREATE TABLE teams (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, manager_email VARCHAR(120));
CREATE TABLE employees (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(120) NOT NULL UNIQUE, display_name VARCHAR(120) NOT NULL, role VARCHAR(20) NOT NULL, team_id BIGINT REFERENCES teams(id), joined_on DATE NOT NULL, password_hash VARCHAR(200) NOT NULL);
CREATE TABLE leave_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id BIGINT NOT NULL REFERENCES employees(id), leave_type VARCHAR(40) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, days NUMERIC(6,1) NOT NULL, state VARCHAR(40) NOT NULL, pending_since TIMESTAMP NOT NULL, manager_comment VARCHAR(500), hr_comment VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_request_employee ON leave_requests(employee_id); CREATE INDEX idx_request_state_pending ON leave_requests(state,pending_since);
CREATE TABLE leave_audit_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id BIGINT NOT NULL REFERENCES leave_requests(id), actor VARCHAR(120) NOT NULL, actor_role VARCHAR(30) NOT NULL, action VARCHAR(40) NOT NULL, previous_state VARCHAR(40), new_state VARCHAR(40) NOT NULL, comment VARCHAR(500), occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, recipient_email VARCHAR(120) NOT NULL, message VARCHAR(500) NOT NULL, read_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
